  static final Map<String, IconData> _iconsByName = {
    for (final option in all) option.name: option.icon,
  };

  static final Map<String, CategoryIconOption> _optionsByName = {
    for (final option in all) option.name: option,
  };

  static List<CategoryIconOption> get fixedOptions {
    return [
      for (final name in fixedNames) _optionsByName[name]!,
    ];
  }

  static IconData iconForName(String? iconName) {
    if (iconName == null) {
      return Icons.category;
    }
    return _iconsByName[iconName] ?? Icons.category;
  }

  static String resolveName(String? iconName) {
    if (iconName == null || !_iconsByName.containsKey(iconName)) {
      return fixedNames.first;
    }
    return iconName;
  }

  static CategoryIconOption? optionForName(String? iconName) {
    if (iconName == null) {
      return null;
    }
    return _optionsByName[iconName];
  }

  static List<CategoryIconOption> search(String query) {
    final matches = all.where((option) => option.matches(query)).toList();
    matches.sort((first, second) => first.label.compareTo(second.label));
    return matches;
  }
}
